mapper.select:
SELECT COALESCE(th.category, 'ETC') AS category,
       COALESCE(SUM(CASE
           WHEN th.transaction_datetime >= #{currentStart}
            AND th.transaction_datetime < #{currentEndExclusive}
           THEN th.amount ELSE 0 END), 0) AS current_amount,
       COALESCE(SUM(CASE
           WHEN th.transaction_datetime >= #{previousStart}
            AND th.transaction_datetime < #{previousEndExclusive}
           THEN th.amount ELSE 0 END), 0) AS previous_amount,
       SUM(CASE
           WHEN th.transaction_datetime >= #{currentStart}
            AND th.transaction_datetime < #{currentEndExclusive}
           THEN 1 ELSE 0 END) AS current_transaction_count,
       SUM(CASE
           WHEN th.transaction_datetime >= #{previousStart}
            AND th.transaction_datetime < #{previousEndExclusive}
           THEN 1 ELSE 0 END) AS previous_transaction_count
FROM transaction_history th
INNER JOIN connected_account account ON account.account_id = th.account_id
INNER JOIN codef_connection connection ON connection.connection_id = account.connection_id
WHERE connection.user_id = #{userId}
  AND account.status = 'ACTIVE'
  AND th.transaction_type = 'WITHDRAW'
  AND TRIM(COALESCE(th.transaction_description, '')) LIKE '체크카드%'
  AND (
      (th.transaction_datetime >= #{previousStart}
       AND th.transaction_datetime < #{previousEndExclusive})
      OR
      (th.transaction_datetime >= #{currentStart}
       AND th.transaction_datetime < #{currentEndExclusive})
  )
GROUP BY COALESCE(th.category, 'ETC')
ORDER BY current_amount DESC, category ASC

SELECT TRIM(th.transaction_description) AS description,
       COALESCE(SUM(CASE
           WHEN th.transaction_datetime >= #{currentStart}
            AND th.transaction_datetime < #{currentEndExclusive}
           THEN th.amount ELSE 0 END), 0) AS current_amount,
       COALESCE(SUM(CASE
           WHEN th.transaction_datetime >= #{previousStart}
            AND th.transaction_datetime < #{previousEndExclusive}
           THEN th.amount ELSE 0 END), 0) AS previous_amount,
       SUM(CASE
           WHEN th.transaction_datetime >= #{currentStart}
            AND th.transaction_datetime < #{currentEndExclusive}
           THEN 1 ELSE 0 END) AS current_transaction_count,
       SUM(CASE
           WHEN th.transaction_datetime >= #{previousStart}
            AND th.transaction_datetime < #{previousEndExclusive}
           THEN 1 ELSE 0 END) AS previous_transaction_count
FROM transaction_history th
INNER JOIN connected_account account ON account.account_id = th.account_id
INNER JOIN codef_connection connection ON connection.connection_id = account.connection_id
WHERE connection.user_id = #{userId}
  AND account.status = 'ACTIVE'
  AND th.transaction_type = 'WITHDRAW'
  AND TRIM(COALESCE(th.transaction_description, '')) LIKE '체크카드%'
  AND th.transaction_description IS NOT NULL
  AND TRIM(th.transaction_description) <> ''
  AND (
      (th.transaction_datetime >= #{previousStart}
       AND th.transaction_datetime < #{previousEndExclusive})
      OR
      (th.transaction_datetime >= #{currentStart}
       AND th.transaction_datetime < #{currentEndExclusive})
)
GROUP BY TRIM(th.transaction_description)
HAVING current_transaction_count > 0
   AND previous_transaction_count > 0
   AND ABS(current_amount - previous_amount)
       <= GREATEST(1000, previous_amount * 0.10)
ORDER BY current_amount DESC, description ASC
LIMIT 5
